WHERE i.item_id IS NOT NULL
AND c.company_id = #{p.companyId}
AND i.company_id = #{p.companyId}
AND i.item_type = 'normal'
AND i.is_default = 1


		AND i.distributor_id IN

			#{did}



		AND i.distributor_id = #{p.distributorId}



	AND i.item_name LIKE CONCAT('%', #{p.itemNameContains}, '%')


	AND (
	i.item_id IN

		#{vid}

	OR i.default_item_id IN

		#{vid2}

	)


	AND i.audit_status = #{p.auditStatus}


	AND i.approve_status = #{p.approveStatus}


	AND i.brand_id = #{p.brandId}


	AND c.goods_id = #{p.goodsIdEq}


	AND a.start_time < #{p.nowEpochSec}
	AND a.end_time > #{p.nowEpochSec}
	AND a.activity_status NOT IN ('fail', 'success')


	AND a.activity_id = #{p.activityIdEq}
